<?php $reference = $_SESSION['submitted_reference'] ?? null; unset($_SESSION['submitted_reference']); $settings = site_settings(); $phone = preg_replace('/\D+/', '', $settings['whatsapp'] ?? ''); $waUrl = ($phone && $reference) ? 'https://wa.me/' . $phone . '?text=' . rawurlencode('Bonjour, je viens de soumettre un projet à la Fondation Samuel Eto’o. Mon numéro de dossier est ' . $reference . '.') : ''; ?>
<section class="section section-paper confirmation-section"><div class="container confirmation-card"><div class="confirmation-icon"><i class="bi bi-check2"></i></div><p class="eyebrow eyebrow-dark"><span></span><?= e(tr('CANDIDATURE ENREGISTRÉE', 'APPLICATION RECEIVED')) ?></p><h1><?= e(tr('Votre candidature a bien été enregistrée.', 'Your application has been received.')) ?></h1><?php if ($reference): ?><p><?= e(tr('Votre numéro de dossier :','Your application reference:')) ?></p><div class="reference-number"><?= e($reference) ?></div><p><?= e(tr('Conservez précieusement ce numéro. Il pourra être utilisé pour suivre votre candidature.', 'Keep this reference safe. You will need it to track your application.')) ?></p><?php else: ?><p><?= e(tr('Aucun nouveau numéro de dossier n’est disponible dans cette session.', 'No new application reference is available in this session.')) ?></p><?php endif; ?><?php if ($waUrl): ?><p class="whatsapp-redirect-notice" id="whatsapp-redirect-notice"><?= e(tr('Vous allez être redirigé vers WhatsApp dans quelques secondes.', 'You will be redirected to WhatsApp in a few seconds.')) ?></p><?php endif; ?><div class="confirmation-actions"><a class="button button-green" href="<?= e(url('track')) ?>"><?= e(tr('Suivre ma candidature','Track my application')) ?> <i class="bi bi-arrow-right"></i></a><?php if($waUrl): ?><a class="button button-outline-dark" href="<?= e($waUrl) ?>"><i class="bi bi-whatsapp"></i> <?= e(tr('Continuer vers WhatsApp maintenant','Continue to WhatsApp now')) ?></a><?php endif; ?><a class="text-link" href="index.php"><?= e(tr('Retour à l’accueil','Back to home')) ?></a></div><p class="form-disclaimer"><?= e(tr('Le dépôt d’une candidature ne garantit pas un financement.','Submitting an application does not guarantee funding.')) ?></p></div></section>
<?php if ($waUrl): ?><script>window.setTimeout(() => { window.location.assign(<?= json_encode($waUrl, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>); }, 5000);</script><?php endif; ?>
